def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate):
        return np.clip(candidate, lb, ub)

    x = rng.uniform(lb, ub, size=dim)
    T = 10 * (ub - lb) / (1 + np.log(budget))
    alpha = 0.99
    sigma = 0.1 * (ub - lb)

    for i in range(int(budget)):
        y = x + rng.normal(size=dim, loc=0, scale=sigma)
        y = clip(y)
        E_new = func(y)
        E_old = func(x)

        if E_new < E_old:
            x = y
        else:
            delta_E = E_new - E_old
            if np.random.rand() < np.exp(-delta_E / T):
                x = y

        T *= alpha
        sigma *= 0.99

    return clip(x)

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    def generate_candidate(sigma, x_best):
        candidate = rng.normal(size=dim) * sigma + x_best
        return clip(candidate)

    def update_sigma(sigma, x_best, func_val):
        if func_val < 1e-6:
            sigma *= 0.9
        else:
            sigma *= 1.01

        return sigma

    def restart(x_best):
        return np.zeros(dim)

    x_best = np.zeros(dim)
    budget_remaining = budget
    sigma = 1.0
    func_val_best = float('inf')

    while budget_remaining > 0 and sigma > 1e-6:
        candidate = generate_candidate(sigma, x_best)
        func_val = func(candidate)

        if func_val < func_val_best:
            x_best = candidate
            func_val_best = func_val

        sigma = update_sigma(sigma, x_best, func_val_best)

        budget_remaining -= 1

    return x_best
